(32, 'Kami akan melanjutkan kerja sama pada tahun-tahun selanjutnya (sesuai kebutuhan).', '', 'level_s', 9, 1, '2023-03-20 03:55:14'),
(33, 'SDM yang ada di Universitas Abdurrab Sesuai dengan keahlian yang kami harapkan dalam menjalin kerja sama ini.', '', 'level_s', 10, 1, '2023-03-20 03:55:26'),
(34, 'SDM dari Universitas Abdurrab yang bekerjasama dengan Instansi kami bekerja secara Profesional.', '', 'level_s', 11, 1, '2023-03-20 03:55:37'),
(35, 'Mohon Bapak/Ibu sebutkan bentuk kerja sama lain yang bisa dilakukan dengan pihak Universitas Abdurrab.', '', 'textfield_s', 12, 1, '2023-03-20 03:56:09'),
(36, 'Mohon Saran dan Masukan Bapak/Ibu untuk evaluasi dan  perbaikan agar kerjasama yang dilakukan lebih baik ke depannya.', '', 'textfield_s', 13, 1, '2023-03-20 03:56:45');
